// One-off cleanup of synthetic accounts left behind by failed staging test runs.
// Staging only, token-protected, manual (no schedule). Every named account must
// pass every check or nothing is deleted; deletion uses the normal account
// deletion service, so certificates are revoked and sessions/tokens removed.
import { deleteAccount } from "./users.js";
import { isStagingTestAddress } from "./email.js";
import { PROBE } from "./staging-probe.js";

export const CLEANUP_ACTOR = "staging-cleanup";
// Addresses generated by tests/remote/staging.mjs (learner and staff).
const TEST_ADDRESS = /^staging-(staff-)?[a-z0-9]+-[a-z0-9]+@academy-staging-test\.invalid$/;
const TEST_ROLES = new Set(["learner", "academy_admin", "content_editor"]);

const one = (env, sql, ...binds) => env.DB.prepare(sql).bind(...binds).first();
const n = async (env, sql, ...binds) => Number((await one(env, sql, ...binds))?.n ?? 0);

/** Facts and pass/fail checks for one account. Never returns the address. */
export async function inspect(env, id, { from, to }) {
  const u = await one(env, "SELECT id, email, created_at FROM users WHERE id = ?", id);
  if (!u) return { id, exists: false, eligible: false, failed: ["exists"] };
  const roles = (await env.DB.prepare("SELECT role, granted_by FROM user_roles WHERE user_id = ?").bind(id).all()).results;
  const facts = {
    roles: roles.map((r) => r.role).sort(),
    enrollments: await n(env, "SELECT COUNT(*) AS n FROM enrollments WHERE user_id = ?", id),
    certificates: await n(env, "SELECT COUNT(*) AS n FROM certificates WHERE user_id = ?", id),
    sessions: await n(env, "SELECT COUNT(*) AS n FROM sessions WHERE user_id = ?", id),
    auth_tokens: await n(env, "SELECT COUNT(*) AS n FROM auth_tokens WHERE user_id = ?", id),
  };
  const zero = async (sql, ...b) => (await n(env, sql, ...b)) === 0;
  const checks = {
    staging_test_domain: isStagingTestAddress(u.email),
    staging_test_address_pattern: TEST_ADDRESS.test(u.email),
    created_in_failed_run_window: u.created_at >= from && u.created_at <= to,
    only_test_roles: roles.every((r) => TEST_ROLES.has(r.role) && (r.role === "learner" || r.granted_by === "staging-test")),
    enrollments_only_in_probe_course: await zero("SELECT COUNT(*) AS n FROM enrollments WHERE user_id = ? AND course_id <> ?", id, PROBE.courseId),
    certificates_only_for_probe_course: await zero("SELECT COUNT(*) AS n FROM certificates WHERE user_id = ? AND course_id <> ?", id, PROBE.courseId),
    no_early_access_record: await zero("SELECT COUNT(*) AS n FROM early_access_registrants WHERE activated_user_id = ? OR email = ?", id, u.email),
    no_linked_sign_in: await zero("SELECT COUNT(*) AS n FROM oauth_accounts WHERE user_id = ?", id),
    no_support_requests: await zero("SELECT COUNT(*) AS n FROM support_requests WHERE user_id = ?", id),
    no_course_feedback: await zero("SELECT COUNT(*) AS n FROM course_feedback WHERE user_id = ?", id),
    no_instructor_profile: await zero("SELECT COUNT(*) AS n FROM instructors WHERE user_id = ?", id),
    no_reviews_or_grading: await zero(
      "SELECT (SELECT COUNT(*) FROM course_reviews WHERE reviewer_id = ?1) + (SELECT COUNT(*) FROM attempt_answers WHERE reviewer_id = ?1) AS n",
      id,
    ),
    no_authored_content: await zero(
      `SELECT (SELECT COUNT(*) FROM draft_courses WHERE updated_by = ?1) + (SELECT COUNT(*) FROM course_revisions WHERE published_by = ?1)
            + (SELECT COUNT(*) FROM ui_translations WHERE updated_by = ?1) + (SELECT COUNT(*) FROM content_translations WHERE updated_by = ?1) AS n`,
      id,
    ),
  };
  const failed = Object.keys(checks).filter((k) => !checks[k]);
  return { id, exists: true, created_at: u.created_at, ...facts, checks, failed, eligible: failed.length === 0 };
}

export async function totals(env) {
  return {
    users: await n(env, "SELECT COUNT(*) AS n FROM users"),
    synthetic_users: await n(env, "SELECT COUNT(*) AS n FROM users WHERE lower(email) LIKE '%@academy-staging-test.invalid'"),
    sessions: await n(env, "SELECT COUNT(*) AS n FROM sessions"),
    auth_tokens: await n(env, "SELECT COUNT(*) AS n FROM auth_tokens"),
    early_access_registrants: await n(env, "SELECT COUNT(*) AS n FROM early_access_registrants"),
    certificates: (await env.DB.prepare("SELECT status, user_id IS NULL AS holder_deleted, COUNT(*) AS n FROM certificates GROUP BY 1, 2 ORDER BY 1, 2").all()).results,
  };
}

/** mode "check" reports only; mode "delete" deletes only if every account is eligible. */
export async function cleanup(env, { ids, from, to, mode }) {
  const before = await totals(env);
  const accounts = [];
  for (const id of ids) accounts.push(await inspect(env, id, { from, to }));
  const allEligible = accounts.every((a) => a.eligible);
  if (mode !== "delete" || !allEligible) return { mode, deleted: 0, refused: mode === "delete" && !allEligible, accounts, before };
  for (const a of accounts) await deleteAccount(env, a.id, CLEANUP_ACTOR);
  const remaining = [];
  for (const a of accounts) {
    remaining.push({
      id: a.id,
      account: await n(env, "SELECT COUNT(*) AS n FROM users WHERE id = ?", a.id),
      sessions: await n(env, "SELECT COUNT(*) AS n FROM sessions WHERE user_id = ?", a.id),
      auth_tokens: await n(env, "SELECT COUNT(*) AS n FROM auth_tokens WHERE user_id = ?", a.id),
      certificates_held: await n(env, "SELECT COUNT(*) AS n FROM certificates WHERE user_id = ?", a.id),
    });
  }
  return { mode, deleted: accounts.length, refused: false, accounts, remaining, before, after: await totals(env) };
}
